"""Original-frame geometry for the one-way roadway parking probes.

This module measures physical facts. It does not choose a legal parallelism
threshold, determine whether a halt is standing or parking, or resolve a
Chapter exception.
"""
from __future__ import annotations

import hashlib
import json
import math
from pathlib import Path


def vector(start, end):
    return (float(end[0]) - float(start[0]), float(end[1]) - float(start[1]))


def unit(value):
    if len(value) != 2 or not all(math.isfinite(float(item)) for item in value):
        raise ValueError("finite XY vector required")
    norm = math.hypot(float(value[0]), float(value[1]))
    if norm <= 0:
        raise ValueError("nonzero XY vector required")
    return (float(value[0]) / norm, float(value[1]) / norm)


def closest_segment(point, polyline):
    if len(polyline) < 2:
        raise ValueError("road edge needs two or more source vertices")
    nearest = None
    for start, end in zip(polyline, polyline[1:]):
        tangent = vector(start, end)
        length2 = sum(value * value for value in tangent)
        if length2 <= 0:
            raise ValueError("road edge has a zero-length segment")
        projection = sum((point[i] - float(start[i])) * tangent[i] for i in (0, 1)) / length2
        projection = min(1.0, max(0.0, projection))
        foot = tuple(float(start[i]) + projection * tangent[i] for i in (0, 1))
        distance = math.dist(point, foot)
        candidate = (distance, unit(tangent), foot)
        if nearest is None or candidate[0] < nearest[0]:
            nearest = candidate
    return nearest


def inside(point, polygon):
    if len(polygon) < 3:
        raise ValueError("roadway needs a source polygon")
    x, y = (float(value) for value in point)
    hits = False
    for start, end in zip(polygon, polygon[1:] + polygon[:1]):
        ax, ay = (float(value) for value in start)
        bx, by = (float(value) for value in end)
        if (ay > y) != (by > y):
            crossing = ax + (y - ay) * (bx - ax) / (by - ay)
            if x < crossing:
                hits = not hits
    return hits


def measure_frame(frame, context):
    body = frame["body_vertices_xy_m"]
    if len(body) != 4 or any(len(point) != 2 for point in body):
        raise ValueError("original body needs four XY corners")
    flat = [float(value) for point in body for value in point]
    if not all(math.isfinite(value) for value in flat):
        raise ValueError("original body coordinates must be finite")
    center = (sum(point[0] for point in body) / 4,
              sum(point[1] for point in body) / 4)
    heading = unit(frame["vehicle_forward_xy"])
    distance, edge, foot = closest_segment(center, context["road_edge_xy_m"])
    lawful = unit(context["lawful_travel_xy"])
    if abs(sum(edge[i] * lawful[i] for i in (0, 1))) < .9:
        raise ValueError("authored edge and lawful direction are inconsistent")
    edge_alignment = abs(sum(heading[i] * edge[i] for i in (0, 1)))
    lawful_alignment = sum(heading[i] * lawful[i] for i in (0, 1))
    return {"frame": frame["frame"], "time_s": frame["time_s"],
            "body_center_xy_m": center, "nearest_edge_xy_m": foot,
            "center_edge_distance_m": distance,
            "parallel_deviation_deg": math.degrees(math.acos(min(1.0, edge_alignment))),
            "lawful_heading_deviation_deg": math.degrees(math.acos(max(-1.0, min(1.0, lawful_alignment)))),
            "heading_lawful_dot": lawful_alignment,
            "body_corners_inside_roadway": sum(inside(point, context["roadway_polygon_xy_m"])
                                               for point in body),
            "engineering_measurement_only": True}


def measure_sequence(frames, context):
    if not frames:
        raise ValueError("original body history is empty")
    numbers = [frame["frame"] for frame in frames]
    times = [frame["time_s"] for frame in frames]
    if (any(type(number) is not int for number in numbers) or
            any(b <= a for a, b in zip(numbers, numbers[1:])) or
            any(type(value) not in (int, float) or not math.isfinite(value) for value in times) or
            any(b <= a for a, b in zip(times, times[1:]))):
        raise ValueError("original frame/time order invalid")
    return {"frames": [measure_frame(frame, context) for frame in frames],
            "lawful_direction_source": context["lawful_direction_source"],
            "road_edge_source": context["road_edge_source"],
            "roadway_source": context["roadway_source"],
            "legal_judgment": "unresolved"}


def load_original(path, expected_sha256, context):
    raw = Path(path).read_bytes()
    if hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("original parking body source hash changed")
    frames = [json.loads(line) for line in raw.decode("utf-8").splitlines() if line.strip()]
    return measure_sequence(frames, context)

"""Four synchronized original camera sources for a standing/parking attempt.

CARLA objects and FFmpeg processes are supplied only when a Native attempt runs.
"""
from __future__ import annotations

import math
import queue
import subprocess
from pathlib import Path


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
RATE_HZ = 20
SIZES = ((1920, 1080), (1280, 720), (1280, 720), (1280, 720))


def camera_poses(scene):
    target = scene["target_pose"]["target_center_xy_m"]
    spawn = scene["spawn_center_xy_m"]
    forward = scene["target_pose"]["target_forward_xy"]
    approach_yaw = math.degrees(math.atan2(target[1] - spawn[1], target[0] - spawn[0]))
    corner = [target[0] - 4 * forward[1], target[1] + 4 * forward[0]]
    corner_yaw = math.degrees(math.atan2(target[1] - corner[1], target[0] - corner[0]))
    return {
        "overview": {"xyz": [target[0], target[1], 18], "yaw": approach_yaw,
                     "pitch": -90, "attached": False},
        "approach": {"xyz": [spawn[0], spawn[1], 5], "yaw": approach_yaw,
                     "pitch": -25, "attached": False},
        "reference_corner": {"xyz": [*corner, 5], "yaw": corner_yaw,
                             "pitch": -40, "attached": False},
        "driver_reference": {"xyz": [0.5, 0, 1.4], "yaw": 0,
                             "pitch": 0, "attached": True},
    }


class CameraCapture:
    def __init__(self, world, vehicle, scene, output, carla, *, popen=None):
        self.sensors = []
        self.processes = {}
        self.exit_codes = {}
        self.queues = {}
        self.closed = False
        popen = popen or subprocess.Popen
        try:
            for name, (width, height) in zip(CAMERAS, SIZES):
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                if blueprint is None:
                    raise ValueError("original RGB camera blueprint missing")
                for key, value in (("image_size_x", width), ("image_size_y", height),
                                   ("fov", 90)):
                    blueprint.set_attribute(key, str(value))
                pose = camera_poses(scene)[name]
                x, y, z = pose["xyz"]
                transform = carla.Transform(carla.Location(x=x, y=y, z=z),
                                            carla.Rotation(yaw=pose["yaw"],
                                                           pitch=pose["pitch"]))
                sensor = (world.spawn_actor(blueprint, transform, attach_to=vehicle)
                          if pose["attached"] else world.spawn_actor(blueprint, transform))
                if sensor is None:
                    raise RuntimeError("original camera spawn failed: " + name)
                self.sensors.append(sensor)
                frames = queue.Queue(maxsize=8)
                self.queues[name] = frames
                sensor.listen(lambda image, q=frames: q.put_nowait(image))
                command = ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error", "-n",
                           "-f", "rawvideo", "-pixel_format", "bgra", "-video_size",
                           f"{width}x{height}", "-framerate", str(RATE_HZ), "-i", "pipe:0",
                           "-an", "-c:v", "ffv1", "-pix_fmt", "bgra",
                           str(Path(output) / (name + ".mkv"))]
                self.processes[name] = popen(command, stdin=subprocess.PIPE,
                                             stderr=subprocess.DEVNULL)
        except BaseException:
            self.close()
            raise

    def append(self, frame):
        for name in CAMERAS:
            image = self.queues[name].get(timeout=15)
            if image.frame != frame:
                raise RuntimeError("camera/world frame mismatch: " + name)
            self.processes[name].stdin.write(image.raw_data)

    def close(self):
        if self.closed:
            return
        self.closed = True
        errors = []
        for sensor in reversed(self.sensors):
            try:
                sensor.stop()
            except BaseException as exc:
                errors.append(repr(exc))
        for name, process in self.processes.items():
            try:
                if process.stdin and not process.stdin.closed:
                    process.stdin.close()
                code = process.wait(timeout=180)
                self.exit_codes[name] = code
                if code != 0:
                    errors.append("camera encoder failed: " + name)
            except BaseException as exc:
                errors.append(repr(exc))
        for sensor in reversed(self.sensors):
            try:
                sensor.destroy()
            except BaseException as exc:
                errors.append(repr(exc))
        if errors:
            raise RuntimeError("; ".join(errors))

"""Independent measured-geometry audit for four C150041 comparison pairs.

Engineering separation checks identify useful original observations. They make
no legal conclusion about the meaning of parallel, standing or parking.
"""
from __future__ import annotations

import math

from parking_scene import ASSIGNMENT


PAIRS = {
    "park_parallelism": ("park_parallel_lawful", "park_angled_lawful", "orientation"),
    "park_heading": ("park_parallel_lawful", "park_parallel_reverse", "heading"),
    "stand_parallelism": ("stand_parallel_lawful", "stand_angled_lawful", "orientation"),
    "stand_heading": ("stand_parallel_lawful", "stand_parallel_reverse", "heading"),
}


def _last_stationary(result):
    intervals = result.get("stationary_intervals")
    if not intervals:
        raise ValueError("comparison lacks original stationary interval")
    last = intervals[-1]["last_frame"]
    matches = [item for item in result["observations"] if item["frame"] == last]
    if len(matches) != 1 or not matches[0]["engineering_stationary"]:
        raise ValueError("comparison stationary frame cannot be joined")
    return matches[0]


def audit(left, right, comparison_id):
    if comparison_id not in PAIRS:
        raise ValueError("unknown exact parking comparison")
    first, second, variable = PAIRS[comparison_id]
    if (left.get("case_id"), right.get("case_id")) != (ASSIGNMENT + "__" + first,
                                                    ASSIGNMENT + "__" + second):
        raise ValueError("comparison case identities or order differ")
    if left.get("source_packet_sha256") != right.get("source_packet_sha256"):
        raise ValueError("comparison source packet differs")
    if left.get("original_history_sha256") == right.get("original_history_sha256"):
        raise ValueError("comparison original histories are identical")
    if left.get("legal_judgment") != "unresolved" or right.get("legal_judgment") != "unresolved":
        raise ValueError("comparison must preserve legal uncertainty")
    a, b = _last_stationary(left), _last_stationary(right)
    if a["body_corners_inside_roadway"] != 4 or b["body_corners_inside_roadway"] != 4:
        raise ValueError("comparison vehicle body leaves reviewed roadway")
    center_gap = math.dist(a["body_center_xy_m"], b["body_center_xy_m"])
    edge_gap = abs(a["center_edge_distance_m"] - b["center_edge_distance_m"])
    if center_gap > 0.35 or edge_gap > 0.35:
        raise ValueError("comparison fixed body placement differs")
    if variable == "orientation":
        if abs(a["lawful_heading_deviation_deg"] - b["lawful_heading_deviation_deg"]) < 10:
            raise ValueError("comparison lacks measured orientation difference")
        separation = abs(a["parallel_deviation_deg"] - b["parallel_deviation_deg"])
        if separation < 10:
            raise ValueError("comparison lacks measured parallelism difference")
    else:
        if abs(a["parallel_deviation_deg"] - b["parallel_deviation_deg"]) > 3:
            raise ValueError("comparison fixed parallel geometry differs")
        separation = abs(a["lawful_heading_deviation_deg"] -
                         b["lawful_heading_deviation_deg"])
        if separation < 90:
            raise ValueError("comparison lacks measured heading difference")
    return {"comparison_id": comparison_id, "case_ids": [left["case_id"], right["case_id"]],
            "source_packet_sha256": left["source_packet_sha256"],
            "original_history_sha256": [left["original_history_sha256"],
                                        right["original_history_sha256"]],
            "controlled_variable": variable,
            "measured_separation_deg": separation,
            "measured_center_gap_m": center_gap,
            "measured_edge_distance_gap_m": edge_gap,
            "engineering_comparison_only": True,
            "legal_judgment": "unresolved",
            "physical_acceptance_claimed": False}

